-- The architecture page shows the path of one request as a diagram (public/Assets/request-flow.en.svg and .cs.svg) followed
-- by the same steps as a numbered list, instead of a text block. Each replacement runs only while the old text block is still there,
-- so the migration is safe to rerun and an edit made later in the Admin is kept.
SET NAMES utf8mb4;

UPDATE cms_articles SET bodytext = REPLACE(bodytext, '```text\npublic/index.php\n  load Composer and application bootstrap\n  Application handles an explicit application route or enabled API route\n  resolve language and match the request to a Site\n  check access and whether a safe full-page cache entry can answer\n  load active Sections for the Site\n    read the configured Boxes for each Section\n      create the namespaced Box with its parent objects\n      Box calls a Model when it needs database content\n      Renderer processes a .tpl file or a .md content source\n  combine section output in the site layout\n  return the HTTP response and optionally store a safe public page copy\n```', '![Diagram of one request: entry, the application, a gate with the full-page cache, building every section and box, the layout and the response. A cache hit skips straight to the response.](/Assets/request-flow.en.svg)\n\n1. **Entry.** `public/index.php` loads Composer and the application bootstrap.\n2. **Application.** It serves an explicit application route or an enabled API route first, then resolves the language and matches the request to a **Site**.\n3. **Gate.** It checks access and whether a safe full-page cache entry can answer. A hit sends the stored copy and skips the rest.\n4. **Build.** It loads the active **Sections** of the Site. Each Section reads its configured **Boxes**. A Box is created with its parent objects, calls a **Model** when it needs database content, and the **Renderer** processes a `.tpl` file or a `.md` source.\n5. **Layout.** The output of the sections is combined in the site layout.\n6. **Response.** The HTTP response is returned and a safe public copy of the page is optionally stored.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/architecture/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('```text\npublic/index.php\n  load Composer and application bootstrap\n  Application handles an explicit application route or enabled API route\n  resolve language and match the request to a Site\n  check access and whether a safe full-page cache entry can answer\n  load active Sections for the Site\n    read the configured Boxes for each Section\n      create the namespaced Box with its parent objects\n      Box calls a Model when it needs database content\n      Renderer processes a .tpl file or a .md content source\n  combine section output in the site layout\n  return the HTTP response and optionally store a safe public page copy\n```', bodytext) > 0;

UPDATE cms_article_translations SET bodytext = REPLACE(bodytext, '```text\npublic/index.php\n  načte Composer a bootstrap aplikace\n  Application obslouží explicitní trasu aplikace nebo zapnuté API\n  určí jazyk a přiřadí požadavek ke Site\n  zkontroluje přístup a zda může odpovědět bezpečná cache celé stránky\n  načte aktivní Section pro Site\n    přečte nakonfigurované Box každé Section\n      vytvoří Box ve svém jmenném prostoru s rodičovskými objekty\n      Box zavolá Model, když potřebuje obsah z databáze\n      Renderer zpracuje soubor .tpl nebo zdroj obsahu .md\n  složí výstupy sekcí v layoutu webu\n  vrátí odpověď HTTP a volitelně uloží bezpečnou veřejnou kopii stránky\n```', '![Diagram jednoho požadavku: vstup, aplikace, brána s cache celé stránky, sestavení každé sekce a boxu, layout a odpověď. Zásah cache přeskočí rovnou na odpověď.](/Assets/request-flow.cs.svg)\n\n1. **Vstup.** `public/index.php` načte Composer a bootstrap aplikace.\n2. **Application.** Nejdřív obslouží explicitní trasu aplikace nebo zapnuté API, pak určí jazyk a přiřadí požadavek ke **Site**.\n3. **Brána.** Zkontroluje přístup a zda může odpovědět bezpečná cache celé stránky. Zásah pošle uloženou kopii a zbytek přeskočí.\n4. **Sestavení.** Načte aktivní **Section** pro Site. Každá Section přečte své nakonfigurované **Box**. Box se vytvoří s rodičovskými objekty, zavolá **Model**, když potřebuje obsah z databáze, a **Renderer** zpracuje soubor `.tpl` nebo zdroj `.md`.\n5. **Layout.** Výstupy sekcí se složí v layoutu webu.\n6. **Odpověď.** Vrátí se odpověď HTTP a volitelně se uloží bezpečná veřejná kopie stránky.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/architecture/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('```text\npublic/index.php\n  načte Composer a bootstrap aplikace\n  Application obslouží explicitní trasu aplikace nebo zapnuté API\n  určí jazyk a přiřadí požadavek ke Site\n  zkontroluje přístup a zda může odpovědět bezpečná cache celé stránky\n  načte aktivní Section pro Site\n    přečte nakonfigurované Box každé Section\n      vytvoří Box ve svém jmenném prostoru s rodičovskými objekty\n      Box zavolá Model, když potřebuje obsah z databáze\n      Renderer zpracuje soubor .tpl nebo zdroj obsahu .md\n  složí výstupy sekcí v layoutu webu\n  vrátí odpověď HTTP a volitelně uloží bezpečnou veřejnou kopii stránky\n```', bodytext) > 0;
